import{_ as t,o as r,c as a,a5 as s}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Vision et périmètre","description":"","frontmatter":{},"headers":[],"relativePath":"produit/index.md","filePath":"produit/index.md","lastUpdated":1793427717000}'),i={name:"produit/index.md"};function o(n,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="vision-et-perimetre" tabindex="-1">Vision et périmètre <a class="header-anchor" href="#vision-et-perimetre" aria-label="Permalink to &quot;Vision et périmètre&quot;">​</a></h1><h2 id="le-produit" tabindex="-1">Le produit <a class="header-anchor" href="#le-produit" aria-label="Permalink to &quot;Le produit&quot;">​</a></h2><p>Un <strong>SaaS de point de vente</strong> capable de gérer <strong>n&#39;importe quel type de magasin</strong> — épicerie, boutique de vêtements, restaurant ou café, services — avec un <strong>cœur commun</strong> (vente, stock, clients, caisse, rapports) et des <strong>modules activés selon le profil</strong> du magasin.</p><div class="tip custom-block"><p class="custom-block-title">Atout n°1 : offline-first</p><p>Rien ne bloque jamais en magasin, même sans internet : vendre, encaisser, imprimer, envoyer en cuisine. Les appareils du magasin se parlent sur le <strong>réseau local</strong> ; le cloud sert à la synchronisation, au back-office et au multi-magasins.</p></div><h2 id="decisions-fondatrices" tabindex="-1">Décisions fondatrices <a class="header-anchor" href="#decisions-fondatrices" aria-label="Permalink to &quot;Décisions fondatrices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Décision</th><th>Choix</th></tr></thead><tbody><tr><td>Modèle</td><td>SaaS multi-tenant : un commerçant = un tenant, 1 à n magasins</td></tr><tr><td>Plateformes</td><td>Applications natives <strong>Android</strong> et <strong>iOS</strong> (tablette et téléphone) + <strong>back-office web</strong></td></tr><tr><td>Stack</td><td>Moteur métier <strong>Kotlin Multiplatform</strong> partagé · UI <strong>Compose</strong> et <strong>SwiftUI</strong> · serveur <strong>Spring Boot Kotlin</strong> · back-office <strong>Angular</strong></td></tr><tr><td>Offline</td><td>Priorité absolue, y compris le temps réel en réseau local (hub)</td></tr><tr><td>Personnalisation</td><td>Thèmes, logo, langue, écrans configurables par magasin et par appareil (white-label)</td></tr><tr><td>Conformité</td><td>Module fiscal par pays : chaînage inaltérable, clôtures, archivage (France), NACEF (Tunisie)</td></tr><tr><td>Performance</td><td><strong>Moins de 100 ms</strong> par action caissier (p95), mesuré en continu</td></tr></tbody></table><h2 id="les-utilisateurs" tabindex="-1">Les utilisateurs <a class="header-anchor" href="#les-utilisateurs" aria-label="Permalink to &quot;Les utilisateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Persona</th><th>Rôle</th><th>Ce qu&#39;il attend</th></tr></thead><tbody><tr><td><strong>Omar</strong>, propriétaire</td><td><code>OWNER</code></td><td>Piloter ses magasins à distance, ne plus perdre de stock ni d&#39;argent, être en règle</td></tr><tr><td><strong>Lina</strong>, gérante</td><td><code>MANAGER</code></td><td>Configurer le catalogue, valider les retours et remises par PIN, suivre la caisse</td></tr><tr><td><strong>Karim</strong>, caissier</td><td><code>CASHIER</code></td><td>Encaisser vite, scanner, imprimer, sans jamais attendre le réseau</td></tr><tr><td><strong>Sami</strong>, serveur</td><td><code>WAITER</code></td><td>Prendre la commande à table, l&#39;envoyer en cuisine, encaisser à la table</td></tr><tr><td><strong>Le chef</strong></td><td><code>KITCHEN</code></td><td>Voir les bons arriver en temps réel, les faire avancer</td></tr><tr><td><strong>Le client</strong></td><td>—</td><td>Ticket clair, paiement par QR (Flouci, Konnect), demain kiosque et menu QR</td></tr></tbody></table><h2 id="ce-que-le-produit-ne-fait-pas-v1" tabindex="-1">Ce que le produit ne fait pas (v1) <a class="header-anchor" href="#ce-que-le-produit-ne-fait-pas-v1" aria-label="Permalink to &quot;Ce que le produit ne fait pas (v1)&quot;">​</a></h2><p>Comptabilité complète (des exports sont prévus), paie, e-commerce complet, encaissement des fonds pour le compte des marchands (le POS orchestre des fournisseurs de paiement, il ne détient jamais l&#39;argent).</p><p>Voir aussi : <a href="/VendoraSystem-docs/produit/profils">profils de magasin et appareils</a> · <a href="/VendoraSystem-docs/produit/feuille-de-route">feuille de route</a> · <a href="/VendoraSystem-docs/specs/00-overview">spécification 00</a> · <a href="/VendoraSystem-docs/produit/brainstorming">brainstorming d&#39;origine</a>.</p>',11)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
